// Parse Octagon Agent commodity quote response and merge all quote fields back with the current Google Sheets row.
// Works with JSON, markdown tables, plain text, and nested Octagon/OpenAI-style payloads.

function getCurrentCommodityRow() {
  try {
    return $('Loop Over Commodity Symbols').item.json || {};
  } catch (e) {}

  try {
    return $('Loop Over Commodity Symbols').first().json || {};
  } catch (e) {}

  return {};
}

function stringifySafe(value) {
  if (typeof value === 'string') return value;
  if (value == null) return '';
  try {
    return JSON.stringify(value, null, 2);
  } catch (e) {
    return String(value);
  }
}

function unwrapText(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;

  if (typeof value.analysis === 'string') return value.analysis;
  if (typeof value.output_text === 'string') return value.output_text;
  if (typeof value.text === 'string') return value.text;
  if (typeof value.response === 'string') return value.response;
  if (typeof value.result === 'string') return value.result;
  if (typeof value.answer === 'string') return value.answer;

  if (value.message?.content) {
    if (typeof value.message.content === 'string') return value.message.content;
    if (Array.isArray(value.message.content)) {
      return value.message.content.map(c => c?.text || c?.content || c?.value || '').join('\n').trim();
    }
  }

  if (Array.isArray(value.content)) {
    return value.content.map(c => c?.text || c?.content || c?.value || '').join('\n').trim();
  }

  if (value.query) {
    try {
      const q = typeof value.query === 'string' ? JSON.parse(value.query) : value.query;
      const text = q?.output?.[0]?.content?.[0]?.text;
      if (text) return text;
    } catch (e) {
      if (typeof value.query === 'string') return value.query;
    }
  }

  return stringifySafe(value);
}

function stripCodeFences(text) {
  return String(text || '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```javascript\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function parseJsonObjectFromText(text) {
  const cleaned = stripCodeFences(text);
  if (!cleaned) return {};

  try {
    const parsed = JSON.parse(cleaned);
    if (parsed && typeof parsed === 'object') return parsed;
  } catch (e) {}

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    const candidate = cleaned.slice(firstBrace, lastBrace + 1);
    try {
      const parsed = JSON.parse(candidate);
      if (parsed && typeof parsed === 'object') return parsed;
    } catch (e) {}
  }

  return {};
}

function flattenObject(obj, prefix = '', out = {}) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return out;

  for (const [key, value] of Object.entries(obj)) {
    const cleanKey = String(key).trim();
    const path = prefix ? `${prefix}.${cleanKey}` : cleanKey;

    if (value && typeof value === 'object' && !Array.isArray(value)) {
      flattenObject(value, path, out);
    } else {
      out[path] = value;
      out[cleanKey] = value;
    }
  }

  return out;
}

function normalizeKey(key) {
  return String(key || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function getFirst(obj, keys, fallback = '') {
  if (!obj || typeof obj !== 'object') return fallback;

  const flat = flattenObject(obj);
  const normalized = {};

  for (const [key, value] of Object.entries(flat)) {
    normalized[normalizeKey(key)] = value;
  }

  for (const key of keys) {
    const direct = flat[key];
    if (direct !== undefined && direct !== null && direct !== '') return direct;

    const norm = normalized[normalizeKey(key)];
    if (norm !== undefined && norm !== null && norm !== '') return norm;
  }

  return fallback;
}

function extractMetric(text, metric) {
  const escapedMetric = metric.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  const tableRegex = new RegExp(`\\|\\s*${escapedMetric}\\s*\\|\\s*([^|]+)\\|`, 'i');
  const tableMatch = String(text || '').match(tableRegex);
  if (tableMatch) return tableMatch[1].trim();

  const labelRegex = new RegExp(`${escapedMetric}\\s*[:\\-–—]\\s*([^\\n|]+)`, 'i');
  const labelMatch = String(text || '').match(labelRegex);
  if (labelMatch) return labelMatch[1].trim();

  return '';
}

function firstMetric(text, labels) {
  for (const label of labels) {
    const value = extractMetric(text, label);
    if (value) return value;
  }
  return '';
}

function joinRange(low, high) {
  if (low && high) return `${low} - ${high}`;
  return low || high || '';
}

const original = getCurrentCommodityRow();
const octagonRaw = $input.first().json;
const raw = stringifySafe(octagonRaw);
const analysis = unwrapText(octagonRaw) || raw;
const parsed = parseJsonObjectFromText(analysis);

const symbol =
  original.Symbol ||
  original.SYMBOL ||
  original.Ticker ||
  original.TICKER ||
  original['Commodity Symbol'] ||
  getFirst(parsed, ['symbol', 'ticker', 'commodity_symbol', 'commoditySymbol', 'quote.symbol', 'quote.ticker']) ||
  firstMetric(analysis, ['Symbol', 'Ticker', 'Commodity Symbol']);

const commodity =
  original.Commodity ||
  original.commodity ||
  getFirst(parsed, ['commodity', 'name', 'commodity_name', 'commodityName', 'quote.commodity', 'quote.name']) ||
  firstMetric(analysis, ['Commodity', 'Name']);

const currentPrice =
  getFirst(parsed, ['current_price', 'currentPrice', 'price', 'last_price', 'lastPrice', 'last', 'quote.current_price', 'quote.price', 'quote.last_price']) ||
  firstMetric(analysis, ['Current Price', 'Last Price', 'Price', 'Current']);

const change =
  getFirst(parsed, ['change', 'price_change', 'priceChange', 'change_percent', 'changePercent', 'percent_change', 'percentChange', 'quote.change']) ||
  firstMetric(analysis, ['Change', 'Price Change', 'Change %', 'Percent Change']);

const dayLow =
  getFirst(parsed, ['day_low', 'dayLow', 'low', 'regularMarketDayLow', 'quote.day_low']) ||
  firstMetric(analysis, ['Day Low', 'Low']);

const dayHigh =
  getFirst(parsed, ['day_high', 'dayHigh', 'high', 'regularMarketDayHigh', 'quote.day_high']) ||
  firstMetric(analysis, ['Day High', 'High']);

const dayRange =
  getFirst(parsed, ['day_range', 'dayRange', 'regularMarketDayRange', 'quote.day_range']) ||
  firstMetric(analysis, ['Day Range', 'Daily Range']) ||
  joinRange(dayLow, dayHigh);

const yearLow =
  getFirst(parsed, ['year_low', 'yearLow', '52_week_low', '52WeekLow', 'fifty_two_week_low', 'quote.year_low']) ||
  firstMetric(analysis, ['Year Low', '52-Week Low', '52 Week Low']);

const yearHigh =
  getFirst(parsed, ['year_high', 'yearHigh', '52_week_high', '52WeekHigh', 'fifty_two_week_high', 'quote.year_high']) ||
  firstMetric(analysis, ['Year High', '52-Week High', '52 Week High']);

const week52Range =
  getFirst(parsed, ['52_week_range', '52WeekRange', 'fifty_two_week_range', 'fiftyTwoWeekRange', 'fifty_two_week', 'week_52_range', 'fifty_two_week_range_position', 'quote.52_week_range', 'quote.fifty_two_week_range']) ||
  firstMetric(analysis, ['52W Range', '52-Week Range', '52 Week Range', 'Year Range']) ||
  joinRange(yearLow, yearHigh);

const volume =
  getFirst(parsed, ['volume', 'trading_volume', 'tradingVolume', 'regularMarketVolume', 'quote.volume']) ||
  firstMetric(analysis, ['Trading Volume', 'Volume']);

const previousClose =
  getFirst(parsed, ['previous_close', 'previousClose', 'prev_close', 'prevClose', 'regularMarketPreviousClose', 'quote.previous_close']) ||
  firstMetric(analysis, ['Previous Close', 'Prev Close']);

const ma50 =
  getFirst(parsed, ['50_day_avg', '50_day_average', 'fifty_day_avg', 'fifty_day_average', '50_day_ma', '50DayAverage', 'quote.50_day_avg']) ||
  firstMetric(analysis, ['50-Day Avg', '50-Day Average', '50-Day MA', '50-Day Moving Average', '50 Day Average']);

const ma200 =
  getFirst(parsed, ['200_day_avg', '200_day_average', 'two_hundred_day_avg', 'two_hundred_day_average', '200_day_ma', '200DayAverage', 'quote.200_day_avg']) ||
  firstMetric(analysis, ['200-Day Avg', '200-Day Average', '200-Day MA', '200-Day Moving Average', '200 Day Average']);

const exchange =
  getFirst(parsed, ['exchange', 'exchangeName', 'fullExchangeName', 'market', 'quote.exchange']) ||
  firstMetric(analysis, ['Exchange', 'Market']);

const date =
  getFirst(parsed, ['quote_time', 'quoteTime', 'as_of', 'asOf', 'timestamp', 'date', 'time', 'metadata.timestamp']) ||
  firstMetric(analysis, ['As Of (UTC)', 'As Of', 'Quote Time', 'Timestamp', 'Date']) ||
  octagonRaw.metadata?.timestamp ||
  new Date().toISOString();

const sourceStatus =
  getFirst(parsed, ['source_status', 'sourceStatus', 'source', 'status', 'provider', 'data_sources', 'dataSources', 'source/status', 'quote.source_status']) ||
  firstMetric(analysis, ['Data Sources', 'Source', 'Status', 'Source/Status']);

return [{
  json: {
    row_number: original.row_number,
    Symbol: symbol,
    Ticker: symbol,
    Commodity: commodity,
    'Current Price': currentPrice,
    Change: change,
    'Day Low': dayLow,
    'Day High': dayHigh,
    'Day Range': dayRange,
    'Year Low': yearLow,
    'Year High': yearHigh,
    '52-Week Range': week52Range,
    'Trading Volume': volume,
    Volume: volume,
    'Previous Close': previousClose,
    '50-Day Average': ma50,
    '200-Day Average': ma200,
    Exchange: exchange,
    Date: date,
    'Octagon Response': analysis,
    'Octagon Source/Status': sourceStatus,
    _parsedQuoteJson: parsed
  }
}];
